using System.Numerics;

namespace ArcadeDodger.Multiplayer;

public sealed partial class Room
{
    // Civilian goals live on the actor, rather than being regenerated by opening radio.
    private bool WorkCivilian(Civilian agent)
    {
        var npc = agent.Ship;
        if (npc.Role == NpcRole.Mercenary)
        {
            var marks = livingPilots
                .Values.Where(s => s.Job == "bounty" && s.JobState == "active")
                .SelectMany(s => s.Targets)
                .ToHashSet();
            var quarry = enemies
                .Where(e => !e.Allied && e.Hull > 0 && marks.Contains(e.Id))
                .MinBy(e => Vector2.DistanceSquared(e.Position, npc.Position));
            if (quarry is not null && Vector2.Distance(npc.Position, quarry.Position) > 700)
            {
                npc.State = "traveling";
                CivilianTravel(npc, quarry.Position, 110, 650);
                return true;
            }
        }
        if (npc.Role == NpcRole.Police)
        {
            var suspect = players
                .Values.Where(p =>
                    p.Connected
                    && p.Hull > 0
                    && !Racing(p)
                    && Living(p).Police == "wanted"
                    && Vector2.DistanceSquared(p.Position, npc.Position) < 1400 * 1400
                )
                .MinBy(p => Vector2.DistanceSquared(p.Position, npc.Position));
            if (suspect is not null)
            {
                npc.State = "fighting";
                CivilianTravel(npc, suspect.Position, 160, 240);
                return true;
            }
        }
        if (npc.Role is not (NpcRole.Miner or NpcRole.Scavenger))
            return false;
        if (agent.Cargo != 0)
        {
            var cargo = worldCargo.FirstOrDefault(c => c.Id == agent.Cargo && c.Owner == -npc.Id);
            if (cargo is null)
            {
                agent.Cargo = 0;
                return true;
            }
            var station = Sector!
                .Locations.Where(l => l.Kind == "station" && FriendlyStation(l.Id))
                .MinBy(l => Vector2.DistanceSquared(l.Position, npc.Position))!;
            npc.State = "traveling";
            CivilianTravel(npc, station.Position, 80, 160);
            var delta = npc.Position - cargo.Position;
            if (delta.LengthSquared() > 70 * 70)
                cargo.Position = MoveShip(
                    cargo.Position,
                    cargo.Position + Vector2.Normalize(delta) * 80 / TickRate,
                    28
                );
            if (Vector2.Distance(cargo.Position, station.Position) < 250)
            {
                worldCargo.Remove(cargo);
                agent.Cargo = 0;
                agent.DepartAt = Tick + 60 * TickRate;
            }
            return true;
        }
        if (Tick < agent.DepartAt)
        {
            npc.State = "docking";
            return true;
        }
        if (npc.Role == NpcRole.Scavenger)
        {
            var signal = worldCargo.FirstOrDefault(c => c.Kind == "anomaly" && !c.Pending);
            if (signal is not null)
            {
                npc.State = "working";
                if (Vector2.Distance(npc.Position, signal.Position) > 150)
                {
                    CivilianTravel(npc, signal.Position, 100, 120);
                    agent.WorkUntil = Tick + 30 * TickRate;
                }
                else if (Tick >= agent.WorkUntil && ServiceLine(npc.Position, signal.Position))
                {
                    worldCargo.Remove(signal);
                    Broadcast(
                        "sector",
                        agent.Name,
                        "Ancient technology secured. Signal has gone quiet."
                    );
                }
                return true;
            }
            var cargo = worldCargo
                .Where(c => c.Kind is "container" or "disabled-ship" && c.Owner == 0 && !c.Pending)
                .MinBy(c => Vector2.DistanceSquared(c.Position, npc.Position));
            if (cargo is null)
                return false;
            npc.State = "working";
            CivilianTravel(npc, cargo.Position, 100, 100);
            if (
                Vector2.Distance(npc.Position, cargo.Position) <= 180
                && ServiceLine(npc.Position, cargo.Position)
            )
            {
                cargo.Owner = -npc.Id;
                agent.Cargo = cargo.Id;
            }
            return true;
        }
        var cache = Sector!
            .Locations.Where(l => l.Kind == "cache")
            .OrderBy(l => l.Id)
            .Skip(agent.Identity % 3)
            .FirstOrDefault();
        if (cache is null)
            return false;
        npc.State = "traveling";
        if (Vector2.Distance(npc.Position, cache.Position) > 150)
        {
            CivilianTravel(npc, cache.Position, 90, 110);
            agent.WorkUntil = Tick + 30 * TickRate;
            return true;
        }
        npc.State = "working";
        if (Tick < agent.WorkUntil)
            return true;
        var before = worldCargo.Count;
        AddCargo("container", npc.Position + new Vector2(80, 0), 30);
        if (worldCargo.Count > before)
        {
            worldCargo[^1].Owner = -npc.Id;
            agent.Cargo = worldCargo[^1].Id;
        }
        agent.WorkUntil = Tick + 30 * TickRate;
        return true;
    }

    private void CivilianTravel(Enemy npc, Vector2 destination, float speed, float stop)
    {
        if (Vector2.Distance(npc.Position, destination) <= stop)
            return;
        var delta = Navigate(npc, destination) - npc.Position;
        if (delta.LengthSquared() < 1)
            return;
        npc.Aim = MathF.Atan2(delta.Y, delta.X);
        npc.Position = MoveShip(
            npc.Position,
            npc.Position + Vector2.Normalize(delta) * speed / TickRate,
            EnemyRadius(npc)
        );
    }
}
